CREATE TABLE "credential_types" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NOT NULL, "description" character varying NULL, "kind" character varying NOT NULL, "namespace" character varying NOT NULL, "managed" boolean NOT NULL DEFAULT false, "inputs" jsonb NULL, "injectors" jsonb NULL, "organization_credential_types" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "credential_types_organizations_credential_types" FOREIGN KEY ("organization_credential_types") REFERENCES "organizations" ("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "credentialtype_namespace" ON "credential_types" ("namespace");
CREATE UNIQUE INDEX "credentialtype_name_organization_credential_types" ON "credential_types" ("name", "organization_credential_types");
CREATE INDEX "credentialtype_kind" ON "credential_types" ("kind");
CREATE TABLE "credentials" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NOT NULL, "description" character varying NULL, "inputs" jsonb NULL, "external" jsonb NULL, "secret_binding" character varying NOT NULL, "credential_type_credentials" bigint NOT NULL, "organization_credentials" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "credentials_credential_types_credentials" FOREIGN KEY ("credential_type_credentials") REFERENCES "credential_types" ("id") ON DELETE NO ACTION, CONSTRAINT "credentials_organizations_credentials" FOREIGN KEY ("organization_credentials") REFERENCES "organizations" ("id") ON DELETE NO ACTION);
CREATE UNIQUE INDEX "credential_name_organization_credentials" ON "credentials" ("name", "organization_credentials");
CREATE TABLE "template_credentials" ("template_id" bigint NOT NULL, "credential_id" bigint NOT NULL, PRIMARY KEY ("template_id", "credential_id"), CONSTRAINT "template_credentials_template_id" FOREIGN KEY ("template_id") REFERENCES "templates" ("id") ON DELETE CASCADE, CONSTRAINT "template_credentials_credential_id" FOREIGN KEY ("credential_id") REFERENCES "credentials" ("id") ON DELETE CASCADE);
